	if err := w.SavePolicy(PolicySpec{
		ID:                "p-direct",
		PayerAccountID:    "payer",
		AllowedAccountIDs: []string{"u1"},
		Operation:         "charge",
		Payee:             "shop",
		StartsAt:          c.t.Add(-time.Hour),
		EndsAt:            c.t.Add(24 * time.Hour),
		MaxPerRequest:     math.MaxInt64,
		MaxTotal:          math.MaxInt64,
