503			t.Fatal(err)
504		}
505		pv, _ := w.Policy("p1")
506		if pv.ReservedTotal != 20 || pv.SpentTotal != 0 {
507			t.Fatalf("quota after cancel = reserved %d spent %d", pv.ReservedTotal, pv.SpentTotal)
508		}
509		// 结算第二笔为 10，结算差额同样释放额度。
510		if _, err := w.Settle("u2", "r2", 10); err != nil {
511			t.Fatal(err)
512		}
513		pv, _ = w.Policy("p1")
514		if pv.ReservedTotal != 0 || pv.SpentTotal != 10 {
515			t.Fatalf("quota after settle = %+v", pv)
516		}
517	}
518	
519	func TestInsufficientBalance(t *testing.T) {
520		w, c := newTestWallet()
521		mustAccount(t, w, "poor", 5)
522		mustAccount(t, w, "u1", 0)
523		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(time.Minute)); err != nil {
524			t.Fatal(err)
525		}
526		spec := validPolicy(c)
527		spec.PayerAccountID = "poor"
528		spec.AllowedAccountIDs = []string{"u1"}
529		if err := w.SavePolicy(spec); err != nil {
530			t.Fatal(err)
531		}
532		in := baseApply()
533		if _, err := w.Apply(in); !errors.Is(err, ErrInsufficientBalance) {
534			t.Fatalf("err = %v, want ErrInsufficientBalance", err)
535		}
536		bal, _ := w.Balance("poor")
537		if bal != (Balances{Available: 5, Reserved: 0}) {
538			t.Fatalf("balance changed on rejection: %+v", bal)
539		}
540	}
541	
542	func TestRejectionLeavesLedgerReasonAndNoMoneyMovement(t *testing.T) {
543		w, _ := setupApply(t)
544		in := baseApply()
545		in.DeviceID = "wrong"
546		if _, err := w.Apply(in); !errors.Is(err, ErrSessionDeviceMismatch) {
547			t.Fatal(err)
548		}
549		all := w.Ledger()
550		if len(all) != 1 || all[0].Kind != LedgerRejection || all[0].RequestID != "r1" || all[0].Amount != 0 {
551			t.Fatalf("rejection entry = %+v", all)
552		}
553		if all[0].Reason == "" {
554			t.Fatal("rejection reason must not be empty")
555		}
556		if len(w.AccountLedger("payer")) != 0 {
557			t.Fatal("rejection must not create money-moving entries")
558		}
559		bal, _ := w.Balance("payer")
560		if bal != (Balances{Available: 100, Reserved: 0}) {
561			t.Fatalf("balance changed: %+v", bal)
