564	
565	func TestLedgerConsistencyAcrossLifecycle(t *testing.T) {
566		w, _ := setupApply(t)
567		if _, err := w.Apply(baseApply()); err != nil {
568			t.Fatal(err)
569		}
570		if _, err := w.Cancel("u1", "r1"); err != nil {
571			t.Fatal(err)
572		}
573		led := w.AccountLedger("payer")
574		if len(led) != 2 || led[0].Kind != LedgerReserve || led[0].Amount != 20 ||
575			led[1].Kind != LedgerRefund || led[1].Amount != 20 {
576			t.Fatalf("ledger = %+v", led)
577		}
578		for _, e := range led {
579			if e.RequestID != "r1" {
580				t.Fatalf("entry missing request link: %+v", e)
581			}
582		}
583		// 余额 = 初始 + 账本求和（settle 为负向，reserve 不影响总额，这里直接核对可用/预留）。
584		bal, _ := w.Balance("payer")
585		if bal.Available != 100 || bal.Reserved != 0 {
586			t.Fatalf("final balance = %+v", bal)
