590	func TestUnknownRequestTerminalOps(t *testing.T) {
591		w, _ := setupApply(t)
592		if _, err := w.Settle("u1", "ghost", 1); !errors.Is(err, ErrRequestNotFound) {
593			t.Fatalf("settle missing err = %v", err)
594		}
595		if _, err := w.Cancel("u1", "ghost"); !errors.Is(err, ErrRequestNotFound) {
596			t.Fatalf("cancel missing err = %v", err)
597		}
598	}
599	
600	func TestConcurrentAppliesSettlesCancels(t *testing.T) {
601		w, c := setupApply(t)
602		// 额度 50：仅能容纳两笔（20+20），并发下不能超扣。
603		const n = 8
604		var wg sync.WaitGroup
605		errs := make([]error, n)
606		wg.Add(n)
607		for i := 0; i < n; i++ {
608			i := i
609			go func() {
610				defer wg.Done()
611				in := baseApply()
612				in.AccountID, in.SessionID, in.DeviceID = "u2", "s2", "dev2"
613				in.RequestID = fmt.Sprintf("c%d", i)
614				_, errs[i] = w.Apply(in)
615			}()
616		}
617		wg.Wait()
618		accepted := 0
619		for _, err := range errs {
620			switch {
621			case err == nil:
622				accepted++
623			case errors.Is(err, ErrQuotaExceeded), errors.Is(err, ErrInsufficientBalance):
624			default:
625				t.Fatalf("unexpected apply err: %v", err)
626			}
627		}
628		if accepted != 2 {
629			t.Fatalf("accepted = %d, want exactly 2", accepted)
630		}
631		bal, _ := w.Balance("payer")
632		if bal.Available+bal.Reserved != 100 || bal.Reserved != 40 {
633			t.Fatalf("balance = %+v, want available 60 / reserved 40", bal)
634		}
635		pv, _ := w.Policy("p1")
636		if pv.ReservedTotal != 40 || pv.ReservedTotal+pv.SpentTotal > 50 {
637			t.Fatalf("shared quota overrun: %+v", pv)
638		}
639	
640		// 释放前两笔占用的额度（忽略未受理编号的错误），再构造单请求终态竞争。
641		for i := 0; i < n; i++ {
642			_, _ = w.Cancel("u2", fmt.Sprintf("c%d", i))
643		}
644		bal, _ = w.Balance("payer")
645		if bal != (Balances{Available: 100, Reserved: 0}) {
646			t.Fatalf("balance after cleanup = %+v", bal)
647		}
648	
649		in := baseApply()
650		in.RequestID = "race1"
651		if _, err := w.Apply(in); err != nil {
652			t.Fatal(err)
653		}
654		var wg2 sync.WaitGroup
655		results := make([]RequestView, 4)
656		opErrs := make([]error, 4)
657		for i := 0; i < 4; i++ {
658			i := i
659			wg2.Add(1)
660			go func() {
661				defer wg2.Done()
662				if i%2 == 0 {
663					results[i], opErrs[i] = w.Settle("u1", "race1", 12)
664				} else {
665					results[i], opErrs[i] = w.Cancel("u1", "race1")
666				}
667			}()
668		}
669		wg2.Wait()
670		states := map[RequestState]int{}
671		for i, err := range opErrs {
672			if err == nil {
673				states[results[i].State]++
674			} else if !errors.Is(err, ErrAlreadySettled) && !errors.Is(err, ErrAlreadyCancelled) {
675				t.Fatalf("unexpected race err: %v", err)
676			}
677		}
678		// 第一个成功操作决定唯一终态：settled 与 cancelled 互斥。
679		if states[RequestSettled] > 0 && states[RequestCancelled] > 0 {
680			t.Fatalf("request reached both terminal states: %v", states)
681		}
682		req, _ := w.Request("u1", "race1")
683		if req.State != RequestSettled && req.State != RequestCancelled {
684			t.Fatalf("request not terminal: %v", req.State)
685		}
686		bal, _ = w.Balance("payer")
687		pv, _ = w.Policy("p1")
688		if bal.Available+bal.Reserved+pv.SpentTotal != 100 || bal.Reserved != 0 {
689			t.Fatalf("balance not conserved after race: %+v policy=%+v", bal, pv)
690		}
691	
692		// 同一请求编号并发重复申请：只预留一次，最终预留 20。
693		const m = 16
694		var wg3 sync.WaitGroup
695		wg3.Add(m)
696		dups := make([]error, m)
697		for i := 0; i < m; i++ {
698			i := i
699			go func() {
700				defer wg3.Done()
701				in := baseApply()
702				in.RequestID = "dup1"
703				_, dups[i] = w.Apply(in)
704			}()
705		}
706		wg3.Wait()
707		for _, err := range dups {
708			if err != nil {
709				t.Fatalf("duplicate apply should be idempotent: %v", err)
710			}
711		}
712		bal, _ = w.Balance("payer")
713		pv2, _ := w.Policy("p1")
714		if bal.Available+bal.Reserved+pv2.SpentTotal != 100 || bal.Reserved != 20 {
715			t.Fatalf("final balance = %+v, want reserved 20", bal)
716		}
717		if pv2.ReservedTotal != 20 || pv2.ReservedTotal+pv2.SpentTotal > 50 {
718			t.Fatalf("shared quota after races: %+v", pv2)
719		}
720		_ = c
721	}
