706		// 已预留请求：会话吊销后仍可结算。
707		if _, err := w.Settle("u1", "r3", 8); err != nil {
708			t.Fatalf("settle reserved after session revoke: %v", err)
709		}
710		// 已预留请求吊销后仍可取消。
711		if _, err := w.Cancel("u1", "r4"); err != nil {
