946		if cancelErr != nil {
947			t.Fatalf("cancel err = %v", cancelErr)
948		}
949		// 两种合法结局：
950		//  - 取消先完成：批准失败 ErrRequestNotPending，余额不动；
951		//  - 批准先完成：取消按已预留规则退回，余额全额退回。
952		bal, _ := w.Balance("payer")
