	if err := w.RevokeSession("sa"); err != nil {
		t.Fatal(err)
	}
	if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); !errors.Is(err, ErrNotApprover) {
		t.Fatalf("revoked payer session err = %v, want ErrNotApprover", err)
	}
}

