1	package wallet
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	// 本文件为“同一笔已预留代付请求同时收到不同实际费用的结算回调”补充回归
11	// 保障：第一次成功结算确定唯一实际费用，相同金额的后续结算幂等返回已有
12	// 结果，不同金额返回 ErrConflict；回调并发到达时也只能有一个金额胜出，
13	// 不能各自成功扣除不同费用，后来的金额也不能覆盖已完成的结算。
14	//
15	// 固定场景（见 setupConcurrentSettle）：
16	//   - 出资账户 payer 初始可用余额 300，使用账户 user 与其不同、自有余额 50；
17	//   - 同一出资账户、同一策略下两笔直接受理的预留：r-main 预估 80、r-other
18	//     预估 40；策略无需审批、未启用预留超时，单次与共享限额、余额均足够；
19	//   - 两笔预留后 payer 为可用 180 / 预留 120，策略预留总额 120、已花费 0；
20	//   - r-main 按两个不同的合法实际费用并发结算，r-other 始终保持已预留。
21	const (
22		racePayerInitial  int64 = 300
23		raceUserInitial   int64 = 50
24		raceMainRequest         = "r-main"
25		raceMainEstimate  int64 = 80
26		raceOtherRequest        = "r-other"
27		raceOtherEstimate int64 = 40
28	)
29	
30	// setupConcurrentSettle 构造上述固定场景，并断言两笔预留完成后的起点状态：
31	// payer 可用 180 / 预留 120，user 自身余额不变，策略预留 120、已花费 0。
32	func setupConcurrentSettle(t *testing.T) (*Wallet, *clock) {
33		t.Helper()
34		w, c := newTestWallet()
35		mustAccount(t, w, "payer", racePayerInitial)
36		mustAccount(t, w, "user", raceUserInitial)
37		if _, err := w.CreateSession("s-user", "user", "dev-user", c.t.Add(time.Hour)); err != nil {
38			t.Fatal(err)
39		}
40		spec := PolicySpec{
41			ID:                "p-settle",
42			PayerAccountID:    "payer",
43			AllowedAccountIDs: []string{"user"},
44			Operation:         "charge",
45			Payee:             "shop",
46			StartsAt:          c.t.Add(-time.Hour),
47			EndsAt:            c.t.Add(time.Hour),
48			// 限额只需容纳两笔预留；不开启审批与预留超时。
49			MaxPerRequest: 100,
50			MaxTotal:      1000,
51		}
52		if err := w.SavePolicy(spec); err != nil {
53			t.Fatal(err)
54		}
55		for _, in := range []RequestInput{
56			settleRaceApply(raceMainRequest, raceMainEstimate),
57			settleRaceApply(raceOtherRequest, raceOtherEstimate),
58		} {
59			view, err := w.Apply(in)
60			if err != nil {
61				t.Fatalf("apply %s: %v", in.RequestID, err)
62			}
63			if view.State != RequestReserved {
64				t.Fatalf("request %s state = %v, want reserved", in.RequestID, view.State)
65			}
66		}
67	
68		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 180, Reserved: 120}) {
69			t.Fatalf("payer starting balance = %+v, want {180 120}", bal)
70		}
71		if bal, _ := w.Balance("user"); bal != (Balances{Available: raceUserInitial, Reserved: 0}) {
72			t.Fatalf("user starting balance = %+v, want own balance untouched", bal)
73		}
74		if pv, _ := w.Policy("p-settle"); pv.ReservedTotal != 120 || pv.SpentTotal != 0 {
75			t.Fatalf("policy starting totals = reserved %d spent %d, want 120/0", pv.ReservedTotal, pv.SpentTotal)
76		}
77		return w, c
78	}
79	
80	func settleRaceApply(requestID string, estimate int64) RequestInput {
81		return RequestInput{
82			PolicyID:     "p-settle",
83			RequestID:    requestID,
84			AccountID:    "user",
85			SessionID:    "s-user",
86			DeviceID:     "dev-user",
87			Operation:    "charge",
88			Payee:        "shop",
89			EstimatedFee: estimate,
90		}
91	}
92	
93	// expectedSettledLedgerLen 返回 r-main 以 winnerFee 胜出后账本的总条数：
94	// 两条原有预留，加一条实际费用扣减；实际费用小于预估时再加一条差额退款，
95	// 实际费用等于预估（含零差额）时不产生退款。
96	func expectedSettledLedgerLen(winnerFee int64) int {
97		n := 3 // r-main 预留 + r-other 预留 + 一条实际费用扣减
98		if winnerFee < raceMainEstimate {
99			n++ // 差额退款（胜出金额为零时也是全额退款一条）
100		}
101		return n
102	}
103	
104	// checkSettledOutcome 校验 r-main 以 winnerFee 成为最终实际费用后的全部可
105	// 观察结果（结算时刻必须是 settledAt，不被任何重复调用改写）：
106	//   - 最终请求为已结算，实际费用为 winnerFee，预估仍为 80，结算时间固定；
107	//   - r-other 保持已预留、实际费用为零，其账本记录原样不变；
108	//   - payer 可用 = 300 - 40(r-other 仍预留) - winnerFee，预留恒为 40；
109	//   - user 自身余额不因代付结算变动；资金守恒：可用 + 预留 + 已花费 = 300；
110	//   - 策略预留总额 40、已花费总额只计胜出实际费用 winnerFee；
111	//   - r-main 只新增一条 payer 的实际扣减（winnerFee，零费用时为零金额记录），
112	//     winnerFee < 80 时另增一条 payer 的差额退款（80-winnerFee），金额为零时
113	//     不产生零金额退款；r-other 仍只有一条 40 的预留记录；
114	//   - 全部资金记录都归 payer，user 名下没有任何资金记录，账本总条数固定，
115	//     重复回调不增加记录。
116	func checkSettledOutcome(t *testing.T, w *Wallet, winnerFee int64, settledAt time.Time) {
117		t.Helper()
118	
119		got, err := w.Request("user", raceMainRequest)
120		if err != nil {
121			t.Fatal(err)
122		}
123		if got.State != RequestSettled {
124			t.Fatalf("r-main state = %v, want settled", got.State)
125		}
126		if got.EstimatedFee != raceMainEstimate || got.ActualFee != winnerFee {
127			t.Fatalf("r-main fees = estimated %d actual %d, want estimated 80 actual %d",
128				got.EstimatedFee, got.ActualFee, winnerFee)
129		}
130		if got.SettledAt.IsZero() || !got.SettledAt.Equal(settledAt) {
131			t.Fatalf("r-main settled at %v, want %v (must not be rewritten)", got.SettledAt, settledAt)
132		}
133	
134		// 同一出资账户、同一策略下的另一笔预留不受影响。
135		other, err := w.Request("user", raceOtherRequest)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if other.State != RequestReserved || other.EstimatedFee != raceOtherEstimate || other.ActualFee != 0 {
140			t.Fatalf("r-other = %+v, want still reserved for 40 with no actual fee", other)
141		}
142	
143		wantAvailable := racePayerInitial - raceOtherEstimate - winnerFee
144		if bal, _ := w.Balance("payer"); bal != (Balances{Available: wantAvailable, Reserved: raceOtherEstimate}) {
145			t.Fatalf("payer balance (winner %d) = %+v, want {%d 40}", winnerFee, bal, wantAvailable)
146		}
147		if bal, _ := w.Balance("user"); bal != (Balances{Available: raceUserInitial, Reserved: 0}) {
148			t.Fatalf("user balance = %+v, want unchanged {%d 0}", bal, raceUserInitial)
149		}
150		pv, err := w.Policy("p-settle")
151		if err != nil {
152			t.Fatal(err)
153		}
154		if pv.ReservedTotal != raceOtherEstimate || pv.SpentTotal != winnerFee {
155			t.Fatalf("policy totals (winner %d) = reserved %d spent %d, want 40/%d",
156				winnerFee, pv.ReservedTotal, pv.SpentTotal, winnerFee)
157		}
158		if payerBal, _ := w.Balance("payer"); payerBal.Available+payerBal.Reserved+pv.SpentTotal != racePayerInitial {
159			t.Fatalf("funds not conserved: %+v + spent %d", payerBal, pv.SpentTotal)
160		}
161	
162		all := w.Ledger()
163		if want := expectedSettledLedgerLen(winnerFee); len(all) != want {
164			t.Fatalf("ledger len (winner %d) = %d, want %d: %+v", winnerFee, len(all), want, all)
165		}
166	
167		// r-main 的全部记录只能是：一条 80 预留、一条 winnerFee 扣减，以及（实际
168		// 小于预估时）一条 80-winnerFee 退款；全部归出资账户。
169		mainEntries := settleRaceEntries(all, raceMainRequest)
170		wantMain := 2
171		if winnerFee < raceMainEstimate {
172			wantMain = 3
173		}
174		if len(mainEntries) != wantMain {
175			t.Fatalf("r-main ledger entries = %d, want %d: %+v", len(mainEntries), wantMain, mainEntries)
176		}
177		var settleCount, refundCount int
178		for _, e := range mainEntries {
179			if e.AccountID != "payer" {
180				t.Fatalf("r-main money entry must belong to payer, got %+v", e)
181			}
182			switch e.Kind {
183			case LedgerReserve:
184				if e.Amount != raceMainEstimate {
185					t.Fatalf("r-main reserve amount = %d, want 80", e.Amount)
186				}
187			case LedgerSettle:
188				settleCount++
189				if e.Amount != winnerFee {
190					t.Fatalf("r-main settle amount = %d, want winner fee %d", e.Amount, winnerFee)
191				}
192				if !e.At.Equal(settledAt) {
193					t.Fatalf("r-main settle at %v, want %v", e.At, settledAt)
194				}
195			case LedgerRefund:
196				refundCount++
197				if want := raceMainEstimate - winnerFee; e.Amount != want {
198					t.Fatalf("r-main refund amount = %d, want %d", e.Amount, want)
199				}
200			default:
201				t.Fatalf("r-main has unexpected ledger entry: %+v", e)
202			}
203		}
204		if settleCount != 1 {
205			t.Fatalf("r-main settle records = %d, want exactly 1", settleCount)
206		}
207		if winnerFee < raceMainEstimate {
208			if refundCount != 1 {
209				t.Fatalf("r-main refund records = %d, want exactly 1", refundCount)
210			}
211		} else if refundCount != 0 {
212			t.Fatalf("r-main refund records = %d, want none when actual equals estimated", refundCount)
213		}
214	
215		// r-other 保持原样：只有一条 40 的预留，没有扣减或退款。
216		otherEntries := settleRaceEntries(all, raceOtherRequest)
217		if len(otherEntries) != 1 {
218			t.Fatalf("r-other ledger entries = %d, want 1: %+v", len(otherEntries), otherEntries)
219		}
220		if e := otherEntries[0]; e.Kind != LedgerReserve || e.Amount != raceOtherEstimate || e.AccountID != "payer" {
221			t.Fatalf("r-other ledger entry = %+v, want single payer reserve of 40", e)
222		}
223	
224		// 全部资金记录归出资账户；使用账户名下没有任何资金或状态记录。
225		payerLedger := w.AccountLedger("payer")
226		if got := countKind(payerLedger, LedgerReserve); got != 2 {
227			t.Fatalf("payer reserve records = %d, want 2", got)
228		}
229		if got := countKind(payerLedger, LedgerSettle); got != 1 {
230			t.Fatalf("payer settle records = %d, want 1", got)
231		}
232		if got := countKind(payerLedger, LedgerRefund); got != boolToInt(winnerFee < raceMainEstimate) {
233			t.Fatalf("payer refund records = %d, want %d", got, boolToInt(winnerFee < raceMainEstimate))
234		}
235		if userLedger := w.AccountLedger("user"); len(userLedger) != 0 {
236			t.Fatalf("user ledger must stay empty, got %+v", userLedger)
237		}
238	}
239	
240	func boolToInt(b bool) int {
241		if b {
242			return 1
243		}
244		return 0
245	}
246	
247	// settleRaceEntries 返回账本中关联指定请求编号的全部记录。
248	func settleRaceEntries(entries []LedgerEntry, requestID string) []LedgerEntry {
249		var out []LedgerEntry
250		for _, e := range entries {
251			if e.RequestID == requestID {
252				out = append(out, e)
253			}
254		}
255		return out
256	}
257	
258	// checkViewIsFinal 断言一次成功返回的结算视图与最终请求完全一致。
259	func checkViewIsFinal(t *testing.T, w *Wallet, got RequestView, winnerFee int64, settledAt time.Time) {
260		t.Helper()
261		if got.State != RequestSettled || got.ActualFee != winnerFee || got.EstimatedFee != raceMainEstimate {
262			t.Fatalf("successful settle view = %+v, want settled actual %d", got, winnerFee)
263		}
264		if !got.SettledAt.Equal(settledAt) {
265			t.Fatalf("successful settle view settled at %v, want %v", got.SettledAt, settledAt)
266		}
267		final, err := w.Request("user", raceMainRequest)
268		if err != nil {
269			t.Fatal(err)
270		}
271		if final.State != got.State || final.ActualFee != got.ActualFee || !final.SettledAt.Equal(got.SettledAt) {
272			t.Fatalf("successful view %+v disagrees with final request %+v", got, final)
273		}
274	}
275	
276	// checkRepeatedCallbacks 校验终态确定后的迟到回调：把时钟向后拨，再次提交
277	// 胜出金额必须原样返回已有已结算结果（实际费用与结算时间都不改写、不重新
278	// 冻结或扣款），提交另一金额仍返回 ErrConflict；这些调用都不增加账本记录，
279	// 其余额、策略金额与 r-other 状态与终态完全一致。
280	func checkRepeatedCallbacks(t *testing.T, w *Wallet, c *clock, winnerFee, loserFee int64, settledAt time.Time) {
281		t.Helper()
282	
283		// 时间明显晚于结算时刻：任何“按当前时刻重写结算时间”的实现都会暴露。
284		c.t = settledAt.Add(time.Minute)
285		ledgerBefore := len(w.Ledger())
286	
287		again, err := w.Settle("user", raceMainRequest, winnerFee)
288		if err != nil {
289			t.Fatalf("repeat settle with winner fee %d: %v", winnerFee, err)
290		}
291		checkViewIsFinal(t, w, again, winnerFee, settledAt)
292	
293		if _, err := w.Settle("user", raceMainRequest, loserFee); !errors.Is(err, ErrConflict) {
294			t.Fatalf("settle with other fee %d err = %v, want ErrConflict", loserFee, err)
295		}
296		// 冲突之后再次提交胜出金额：仍是原结果，冲突调用不得“重新打开”请求。
297		again2, err := w.Settle("user", raceMainRequest, winnerFee)
298		if err != nil {
299			t.Fatalf("repeat winner settle after conflict: %v", err)
300		}
301		checkViewIsFinal(t, w, again2, winnerFee, settledAt)
302		// 另一金额再来一次仍然冲突。
303		if _, err := w.Settle("user", raceMainRequest, loserFee); !errors.Is(err, ErrConflict) {
304			t.Fatalf("second settle with other fee %d err = %v, want ErrConflict", loserFee, err)
305		}
306	
307		if len(w.Ledger()) != ledgerBefore {
308			t.Fatalf("repeated callbacks changed ledger %d -> %d", ledgerBefore, len(w.Ledger()))
309		}
310		// 账本不增、余额不改写、预留不重新冻结、结算时间不变。
311		checkSettledOutcome(t, w, winnerFee, settledAt)
312	}
313	
314	// raceSettleBias 控制两个结算 goroutine 的起跑方式：simultaneous 同时放行；
315	// aFirst/bFirst 让指定 goroutine 先取得一小段起跑优势，使“任一金额先完成”
316	// 的两种先后顺序都能在并发 harness 下被确定性地观察到，而不依赖调度器运气。
317	type raceSettleBias int
318	
319	const (
320		raceSimultaneous raceSettleBias = iota
321		raceAFirst
322		raceBFirst
323	)
324	
325	// raceSettlePair 让 feeA 与 feeB 两个不同的合法实际费用从各自的 goroutine
326	// 并发结算同一笔 r-main，断言恰好一个金额成功、另一个返回 ErrConflict，且
327	// 成功视图与最终请求一致。bias 控制起跑先后（见 raceSettleBias）。返回胜出
328	// 金额与失败金额。
329	func raceSettlePair(t *testing.T, w *Wallet, settledAt time.Time, feeA, feeB int64, bias raceSettleBias) (winner, loser int64) {
330		t.Helper()
331		if feeA == feeB {
332			t.Fatalf("race pair must use distinct fees, got %d/%d", feeA, feeB)
333		}
334		fees := []int64{feeA, feeB}
335		views := make([]RequestView, 2)
336		errs := make([]error, 2)
337		// 每个 goroutine 独立起跑闸门：同时放行时一起关闭，偏向某一方时先关闭
338		// 它的闸门、稍候再关闭另一个。
339		gates := []chan struct{}{make(chan struct{}), make(chan struct{})}
340		release := func() {
341			switch bias {
342			case raceAFirst:
343				close(gates[0])
344				time.Sleep(2 * time.Millisecond)
345				close(gates[1])
346			case raceBFirst:
347				close(gates[1])
348				time.Sleep(2 * time.Millisecond)
349				close(gates[0])
350			default:
351				close(gates[0])
352				close(gates[1])
353			}
354		}
355	
356		var wg sync.WaitGroup
357		for i, fee := range fees {
358			i, fee := i, fee
359			wg.Add(1)
360			go func() {
361				defer wg.Done()
362				<-gates[i]
363				views[i], errs[i] = w.Settle("user", raceMainRequest, fee)
364			}()
365		}
366		release()
367		wg.Wait()
368	
369		successes := 0
370		winner, loser = -1, -1
371		for i, fee := range fees {
372			switch {
373			case errs[i] == nil:
374				successes++
375				winner = fee
376				checkViewIsFinal(t, w, views[i], fee, settledAt)
377			case errors.Is(errs[i], ErrConflict):
378				loser = fee
379			default:
380				t.Fatalf("concurrent settle fee %d err = %v, want nil or ErrConflict", fee, errs[i])
381			}
382		}
383		if successes != 1 || winner < 0 || loser < 0 {
384			t.Fatalf("concurrent settles must yield exactly one success and one conflict, got winner %d loser %d errs %v",
385				winner, loser, errs)
386		}
387		return winner, loser
388	}
389	
390	// TestSettleWinnerOutcomes 顺序确定每种合法胜出金额下的完整结果，保证并发
391	// 测试中无论哪个金额先完成，期望口径都一致：
392	//   - 30 胜出：可用 230 / 预留 40，已花费 30，差额退款 50；
393	//   - 70 胜出：可用 190 / 预留 40，已花费 70，差额退款 10；
394	//   - 0  胜出（零费用边界）：仍为已结算，可用 260 / 预留 40，已花费 0，
395	//     全额退回 80，扣减记录为零金额；
396	//   - 80 胜出（预估全额边界）：可用 180 / 预留 40，已花费 80，只扣减、
397	//     不产生零金额退款。
398	func TestSettleWinnerOutcomes(t *testing.T) {
399		cases := []struct {
400			name          string
401			winner, loser int64
402			wantAvailable int64
403			wantRefund    int64
404		}{
405			{"winner-30", 30, 70, 230, 50},
406			{"winner-70", 70, 30, 190, 10},
407			{"winner-zero-full-refund", 0, 80, 260, 80},
408			{"winner-full-no-refund", 80, 0, 180, 0},
409		}
410		for _, tc := range cases {
411			t.Run(tc.name, func(t *testing.T) {
412				w, c := setupConcurrentSettle(t)
413				settledAt := c.t.Add(10 * time.Second)
414				c.t = settledAt
415	
416				view, err := w.Settle("user", raceMainRequest, tc.winner)
417				if err != nil {
418					t.Fatalf("settle winner %d: %v", tc.winner, err)
419				}
420				checkViewIsFinal(t, w, view, tc.winner, settledAt)
421				checkSettledOutcome(t, w, tc.winner, settledAt)
422	
423				// 另一金额（零或预估全额同样合法）不能改写已完成的结算。
424				if _, err := w.Settle("user", raceMainRequest, tc.loser); !errors.Is(err, ErrConflict) {
425					t.Fatalf("settle other fee %d err = %v, want ErrConflict", tc.loser, err)
426				}
427				checkRepeatedCallbacks(t, w, c, tc.winner, tc.loser, settledAt)
428	
429				// 显式复核本用例点名的可用余额与差额退款金额。
430				if bal, _ := w.Balance("payer"); bal.Available != tc.wantAvailable || bal.Reserved != raceOtherEstimate {
431					t.Fatalf("payer balance = %+v, want {%d 40}", bal, tc.wantAvailable)
432				}
433				all := w.Ledger()
434				refunds := settleRaceEntries(all, raceMainRequest)
435				var refundAmount int64 = -1
436				for _, e := range refunds {
437					if e.Kind == LedgerRefund {
438						refundAmount = e.Amount
439					}
440				}
441				if tc.wantRefund == 0 {
442					if refundAmount != -1 {
443						t.Fatalf("unexpected refund %d, want none", refundAmount)
444					}
445				} else if refundAmount != tc.wantRefund {
446					t.Fatalf("refund amount = %d, want %d", refundAmount, tc.wantRefund)
447				}
448			})
449		}
450	}
451	
452	// TestConcurrentSettleDifferentFees：同一笔预留同时收到两笔不同实际费用的
453	// 结算回调时，先成功者确定唯一实际费用，另一回调只能 ErrConflict；任一金
454	// 额先完成都合法，最终余额、策略已花费、使用账户余额、另一笔预留与账本
455	// 都只按胜出金额解释。随后的重复回调沿用幂等与冲突规则且不改写终态。
456	//
457	// 金额对覆盖常规差额（30/70）与两个合法边界（零/预估全额）。每对金额都在
458	// 三种起跑方式下多轮运行：同时放行、feeA 先放行、feeB 先放行，从而确定性
459	// 地覆盖两种回调先后顺序而不依赖调度运气；断言对实际胜出者自适应，但要求
460	// 两个金额都至少胜出一次，否则该先后顺序未被真正验证。
461	func TestConcurrentSettleDifferentFees(t *testing.T) {
462		const iterations = 24
463		biases := []struct {
464			name string
465			mode raceSettleBias
466		}{
467			{"simultaneous", raceSimultaneous},
468			{"feeA-first", raceAFirst},
469			{"feeB-first", raceBFirst},
470		}
471		pairs := [][2]int64{
472			{30, 70},
473			{0, raceMainEstimate},
474		}
475		for _, pair := range pairs {
476			wins := map[int64]int{}
477			for _, b := range biases {
478				for i := 0; i < iterations; i++ {
479					w, c := setupConcurrentSettle(t)
480					settledAt := c.t.Add(10 * time.Second)
481					c.t = settledAt
482	
483					winner, loser := raceSettlePair(t, w, settledAt, pair[0], pair[1], b.mode)
484					wins[winner]++
485					// 唯一终态：余额、额度、账本全部只按胜出金额解释。
486					checkSettledOutcome(t, w, winner, settledAt)
487					// 迟到的胜出金额幂等、失败金额持续冲突，均不再扣款或记账。
488					checkRepeatedCallbacks(t, w, c, winner, loser, settledAt)
489				}
490			}
491			if len(wins) != 2 {
492				t.Fatalf("pair %v: each fee must win at least once, got winner distribution %v", pair, wins)
493			}
494			t.Logf("pair %v winner distribution: %v", pair, wins)
495		}
496	}
497

